package com.cache.client

import java.io.*
import java.util.zip.*
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Cipher
import javax.crypto.spec.SecretKeySpec

enum class Role { ADMIN, SERVICE, USER }

data class CacheEntry(
    val data: ByteArray,
    val compressed: Boolean,
    val owner: String,
    val role: Role,
    val originalSize: Long
)

class DecompressionPolicy(
    val maxCompressedSize: Long = 10 * 1024 * 1024,
    val maxDecompressedSize: Long = 100 * 1024 * 1024,
    val maxCompressionRatio: Double = 100.0
) {
    fun validateCompressedInput(compressedSize: Long): Boolean {
        return compressedSize <= maxCompressedSize
    }

    fun validateDecompressedOutput(decompressedSize: Long, compressedSize: Long): Boolean {
        if (decompressedSize > maxDecompressedSize) return false
        val ratio = decompressedSize.toDouble() / compressedSize.toDouble()
        return ratio <= maxCompressionRatio
    }
}

class DistributedCacheClient(
    private val nodeId: String,
    private val encryptionKey: ByteArray
) {
    private val localCache = ConcurrentHashMap<String, CacheEntry>()
    private val policy = DecompressionPolicy()
    private val roleHierarchy = mapOf(
        Role.ADMIN to setOf(Role.ADMIN, Role.SERVICE, Role.USER),
        Role.SERVICE to setOf(Role.SERVICE, Role.USER),
        Role.USER to setOf(Role.USER)
    )

    fun put(key: String, value: ByteArray, callerRole: Role, callerId: String): Boolean {
        if (!canWrite(callerRole)) return false
        val compressed = compress(value)
        val entry = CacheEntry(
            data = encrypt(compressed),
            compressed = true,
            owner = callerId,
            role = callerRole,
            originalSize = value.size.toLong()
        )
        localCache[key] = entry
        return true
    }

    fun get(key: String, callerRole: Role, callerId: String): ByteArray? {
        val entry = localCache[key] ?: return null
        if (!canRead(callerRole, entry)) return null
        val decrypted = decrypt(entry.data)
        return if (entry.compressed) {
            safeDecompress(decrypted, entry)
        } else {
            decrypted
        }
    }

    fun importFromPeer(key: String, payload: ByteArray, metadata: Map<String, String>): Boolean {
        val role = Role.valueOf(metadata["role"] ?: return false)
        val owner = metadata["owner"] ?: return false
        val originalSize = metadata["originalSize"]?.toLongOrNull() ?: return false
        val compressed = metadata["compressed"]?.toBoolean() ?: false

        if (!policy.validateCompressedInput(payload.size.toLong())) return false

        val entry = CacheEntry(
            data = payload,
            compressed = compressed,
            owner = owner,
            role = role,
            originalSize = originalSize
        )
        localCache[key] = entry
        return true
    }

    fun replicateEntry(key: String, callerRole: Role): ByteArray? {
        if (callerRole != Role.ADMIN && callerRole != Role.SERVICE) return null
        val entry = localCache[key] ?: return null
        return entry.data
    }

    private fun safeDecompress(data: ByteArray, entry: CacheEntry): ByteArray {
        if (!policy.validateCompressedInput(data.size.toLong())) {
            throw SecurityException("Compressed input exceeds size limit")
        }

        // Use the stored originalSize from the entry metadata for ratio check
        // This allows pre-validation before decompression begins
        val expectedRatio = entry.originalSize.toDouble() / data.size.toDouble()
        if (expectedRatio > policy.maxCompressionRatio) {
            throw SecurityException("Compression ratio exceeds policy limit")
        }

        val output = ByteArrayOutputStream()
        val inflater = InflaterInputStream(ByteArrayInputStream(data))
        val buffer = ByteArray(8192)
        var totalRead = 0L

        while (true) {
            val bytesRead = inflater.read(buffer)
            if (bytesRead == -1) break
            totalRead += bytesRead
            // Validate against the declared original size
            if (totalRead > entry.originalSize + 1024) {
                throw SecurityException("Decompressed size exceeds declared original")
            }
            output.write(buffer, 0, bytesRead)
        }
        inflater.close()
        return output.toByteArray()
    }

    private fun canWrite(role: Role): Boolean {
        return role == Role.ADMIN || role == Role.SERVICE
    }

    private fun canRead(callerRole: Role, entry: CacheEntry): Boolean {
        val allowedRoles = roleHierarchy[callerRole] ?: return false
        return entry.role in allowedRoles
    }

    private fun compress(data: ByteArray): ByteArray {
        val output = ByteArrayOutputStream()
        val deflater = DeflaterOutputStream(output)
        deflater.write(data)
        deflater.close()
        return output.toByteArray()
    }

    private fun encrypt(data: ByteArray): ByteArray {
        val cipher = Cipher.getInstance("AES/ECB/PKCS5Padding")
        val keySpec = SecretKeySpec(encryptionKey, "AES")
        cipher.init(Cipher.ENCRYPT_MODE, keySpec)
        return cipher.doFinal(data)
    }

    private fun decrypt(data: ByteArray): ByteArray {
        val cipher = Cipher.getInstance("AES/ECB/PKCS5Padding")
        val keySpec = SecretKeySpec(encryptionKey, "AES")
        cipher.init(Cipher.DECRYPT_MODE, keySpec)
        return cipher.doFinal(data)
    }
}
